//! Pre-rasterized Inter splash / login type (generated by tools/gen_splash_type.py)
//!
//! Packed little-endian header: width:u16, height:u16, then width*height alpha bytes.

#[derive(Clone, Copy)]
pub struct SplashBitmap {
    pub width: u16,
    pub height: u16,
    pub pixels: &'static [u8],
}

const fn parse(raw: &'static [u8]) -> SplashBitmap {
    let width = u16::from_le_bytes([raw[0], raw[1]]);
    let height = u16::from_le_bytes([raw[2], raw[3]]);
    SplashBitmap {
        width,
        height,
        pixels: raw.split_at(4).1,
    }
}

pub static LOGO: SplashBitmap = parse(include_bytes!("../../fonts/splash/logo.bin"));

pub static TAGLINE: SplashBitmap = parse(include_bytes!("../../fonts/splash/tagline.bin"));

pub static VERSION: SplashBitmap = parse(include_bytes!("../../fonts/splash/version.bin"));

pub static STATUS: SplashBitmap = parse(include_bytes!("../../fonts/splash/status.bin"));

pub static LOGIN_TITLE: SplashBitmap = parse(include_bytes!("../../fonts/splash/login_title.bin"));

pub static LOGIN_SUB: SplashBitmap = parse(include_bytes!("../../fonts/splash/login_sub.bin"));

pub static MENU_TITLE: SplashBitmap = parse(include_bytes!("../../fonts/splash/menu_title.bin"));
